namespace ghidra.app.plugin.core.symboltree.nodes;





using generic.theme;
using ghidra.app.util;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.model.symbol;
using resources;

public class ClassSymbolNode : SymbolNode {
	static readonly DataFlavor LOCAL_DATA_FLAVOR =
		new SymbolTreeDataFlavor("Symbol Tree Data Flavor - Local Classes");
	static readonly DataFlavor GLOBAL_DATA_FLAVOR =
		new SymbolTreeDataFlavor("Symbol Tree Data Flavor - Global Classes");

	private static readonly Icon CLASS_ICON = new GIcon("icon.plugin.symboltree.node.class");
	private static readonly Icon DISABLED_CLASS_ICONDISABLED_CLASS_ICON =
		ResourceManager.getDisabledIcon(CLASS_ICON);

	ClassSymbolNode(Program program, Symbol symbol) : base(program, symbol)
    {

	}

	/* @Override */
	public Icon getIcon(bool expanded) {
		if (isCut()) {
			return DISABLED_CLASS_ICONDISABLED_CLASS_ICON;
		}
		return CLASS_ICON;
	}

	/* @Override */
	public DataFlavor getNodeDataFlavor() {
		return symbol.isGlobal() ? GLOBAL_DATA_FLAVOR : LOCAL_DATA_FLAVOR;
	}

	/* @Override */
	public bool supportsDataFlavors(DataFlavor[] dataFlavors) {
		foreach (DataFlavor flavor in dataFlavors) {
			if (symbol.isExternal()) {
				if (isExternal(flavor)) {
					return true;
				}
			}
			if (isLabelOrFunction(flavor)) {
				return true;
			}

			if (isProgramSelection(flavor)) {
				return true;
			}
		}
		return false;
	}

	private bool isProgramSelection(DataFlavor flavor) {
		Class<object> clazz = flavor.getRepresentationClass();
		return typeof(SelectionTransferData).equals(clazz);
	}

	private bool isExternal(DataFlavor dataFlavor) {
		return dataFlavor == CodeSymbolNode.EXTERNAL_DATA_FLAVOR ||
			dataFlavor == FunctionSymbolNode.EXTERNAL_DATA_FLAVOR;
	}

	private bool isLabelOrFunction(DataFlavor dataFlavor) {
		return dataFlavor == CodeSymbolNode.GLOBAL_DATA_FLAVOR ||
			dataFlavor == CodeSymbolNode.LOCAL_DATA_FLAVOR ||
			dataFlavor == FunctionSymbolNode.GLOBAL_DATA_FLAVOR ||
			dataFlavor == FunctionSymbolNode.LOCAL_DATA_FLAVOR;

	}

	/* @Override */
	public Namespace getNamespace() {
		return (Namespace) symbol.getObject();
	}

	/* @Override */
	public bool canCut() {
		return true;
	}
}
